def paragraphs(text,esc):return ''.join('<p>'+esc(p.strip())+'</p>'for p in text.split('\n\n')if p.strip())

def build_guides(page,titles,esc,base):
 for g in GUIDE_ARTICLES:
  path='/blog/'+g['slug']+'/'
  body='<article class="prose"><p class="eyebrow">ANILOVE INDIA · WATCHING GUIDE</p><h1>'+esc(g['title'])+'</h1><blockquote><p>'+esc(g['answer'])+'</p></blockquote><p class="byline">AniLove India editorial desk · 18 October 2026 · AI-assisted guide based on the linked sources</p>'
  for heading,text in g['sections']:body+='<h2>'+esc(heading)+'</h2>'+paragraphs(text,esc)
  if g['slug'].startswith('ragna-'):
   t=next(t for t in titles if t['id']=='ragna-crimson');s=next(s for s in t['seasons']if s['audio_language']=='Hindi');numbers={int(e['number'])for e in s['episodes']if str(e['number']).isdigit()}
   body+='<h2>Current checked Hindi episode links</h2><p>Checked individually: '+', '.join(map(str,sorted(numbers)))+'. Verification date: '+esc(s['last_checked'])+'. This is an available selection; actual India playback is unverified.</p><table><thead><tr><th>Episode</th><th>Hindi upload</th></tr></thead><tbody>'+''.join('<tr><td>'+esc(e['number'])+'</td><td><a href="/watch/'+s['id']+'/'+e['number']+'/">'+esc(e['title'])+'</a></td></tr>'for e in s['episodes'])+'</tbody></table><p><a href="/title/ragna-crimson/">Open Ragna Crimson and its official playlist player →</a></p>'
  else:
   body+='<h2>Compare the three viewing choices</h2><table><thead><tr><th>Edition</th><th>Spoken audio</th><th>What to check</th></tr></thead><tbody><tr><td>Hindi dub</td><td>Hindi</td><td>Hindi edition and numbered episode</td></tr><tr><td>English dub</td><td>English</td><td>English edition and its coverage</td></tr><tr><td>English-subtitled original</td><td>Original language</td><td>Audio evidence and English subtitles</td></tr></tbody></table><p><a href="/seasons/">Browse seasons and language editions →</a> · <a href="/discover/hindi-anime-12-episode-seasons/">Hindi editions with 12 individual episode links</a></p>'
  body+='<h2>Frequently asked questions</h2>'+''.join('<details open><summary>'+esc(q)+'</summary><p>'+esc(a)+'</p></details>'for q,a in g['faqs'])+'<h2>Sources and useful links</h2><ul>'+''.join('<li><a href="'+esc(url)+'">'+esc(label)+'</a></li>'for label,url in g['sources'])+'</ul><p><a href="/blog/">More watching guides</a> · <a href="/contact/">Request an episode</a></p></article>'
  schema={'@context':'https://schema.org','@graph':[{'@type':'BlogPosting','headline':g['title'],'description':g['summary'],'datePublished':DATE,'dateModified':DATE,'inLanguage':'en-IN','mainEntityOfPage':base+path,'author':{'@type':'Organization','name':'AniLove India editorial desk','url':base+'/editorial-team/'},'publisher':{'@type':'Organization','name':'AniLove India','url':base+'/'}},{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}}for q,a in g['faqs']]},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':base+'/'},{'@type':'ListItem','position':2,'name':'Journal','item':base+'/blog/'},{'@type':'ListItem','position':3,'name':g['title'],'item':base+path}]}]}
  page(path,g['title'],body,g['summary'],schema)
 build_short_collection(page,titles,esc,base)

def build_short_collection(page,titles,esc,base):
 path='/discover/hindi-anime-12-episode-seasons/';name='Hindi Anime Seasons with 12 Individual Episode Links';rows=[]
 for t in titles:
  if t['category']!='anime-series':continue
  for s in t['seasons']:
   if s.get('audio_language')=='Hindi'and s.get('embed_checked')and {str(e['number'])for e in s['episodes']}=={str(n)for n in range(1,13)}:rows.append((t,s))
 intro='Choose a Hindi anime season or edition with separate checked links numbered 1–12. This collection describes the listed uploads, not the length of the whole franchise or certified playback.'
 body='<article class="prose"><p class="eyebrow">ANILOVE INDIA · EPISODE COLLECTION</p><h1>'+name+'</h1><p class="lead">'+intro+'</p><h2>A manageable first season</h2><p>A twelve-link edition gives you a clear starting point when you want to try an anime without choosing a long franchise at random. The collection checks the episode numbers in our current catalogue: each listed Hindi edition has twelve individual uploads numbered 1 through 12. A single compilation does not qualify as twelve separate links.</p><p>A season can still belong to a much larger story. SPY × FAMILY and One-Punch Man have other seasons, so finishing the listed edition is different from finishing the franchise. Check the season label before starting, particularly when this collection links a later season.</p><h2>Choose an edition</h2><table><thead><tr><th>Anime</th><th>Hindi edition</th><th>Episode links</th></tr></thead><tbody>'+''.join('<tr><td>'+esc(t['title'])+'</td><td><a href="/title/'+t['id']+'/#'+s['id']+'">'+esc(s['label'])+'</a></td><td><a href="/season/'+s['id']+'/">1–12</a></td></tr>'for t,s in rows)+'</tbody></table><h2>Check the story order and player</h2><p>Use the edition link to see its numbered buttons. Open episode 1 only when it is the beginning of the season you intend to watch. Later-season episode 1 is not necessarily the beginning of the anime. The player loads after you press Play, and the uploader controls current availability.</p><p>These entries passed individual source metadata checks, including explicit Hindi audio evidence, runtime, India country metadata and embedding. Actual India playback remains unobserved. A missing or restricted upload should be reported with its title, season and episode number.</p><p>This page updates from the catalogue when the site is rebuilt. If a source changes or an edition gains an additional special or compilation, it may no longer match this exact twelve-link collection. The full title page remains the place to inspect all available editions.</p><p><a href="/blog/anime-dub-vs-sub-language-guide/">Choose your audio and subtitles</a> · <a href="/category/anime-series/">All anime series</a> · <a href="/contact/">Request an episode</a></p></article>'
 schema={'@context':'https://schema.org','@type':'CollectionPage','name':name,'description':intro,'url':base+path,'inLanguage':'en-IN','mainEntity':{'@type':'ItemList','numberOfItems':len(rows),'itemListElement':[{'@type':'ListItem','position':i+1,'name':t['title']+' — '+s['label'],'url':base+'/season/'+s['id']+'/'}for i,(t,s)in enumerate(rows)]}}
 page(path,name,body,intro,schema)
